// Upper-case the breed and add a label column.
func Apply(b *sdb.Batch) (*sdb.Batch, error) {
	breed := b.Col("breed")
	for i := range b.Rows {
		if s, ok := b.Rows[i][breed].(string); ok {
			b.Rows[i][breed] = strings.ToUpper(strings.TrimSpace(s))
		}
	}
	b.AddCol("label", "", func(row int) any {
		return fmt.Sprintf("%v (%v)", b.Get(row, "name"), b.Get(row, "age"))
	})
	return b, nil
}
